python3 -c "
import json
with open('/app/resources/treasury_bulletin_1982_11.json', 'r') as f:
    data = json.load(f)

# Search for elements containing 'Sales' 'Redemptions' 'Amount outstanding' and 1982 months
for elem in data['document']['elements']:
    content = elem.get('content', '') or ''
    if 'Sales' in content and 'Redemptions' in content and 'Amount outstanding' in content and '1982' in content:
        print('Found table with relevant columns!')
        # Look for July, Aug, Sept in content
        lines = content.split('<tr>')
        for line in lines:
            if 'July' in line and '1982' in line or 'July</td>' in line:
                print('July line:', line[:500])
            if 'Aug' in line and '1982' in line or 'Aug</td>' in line:
                print('Aug line:', line[:500])
            if 'Sept' in line and '1982' in line or 'Sept</td>' in line:
                print('Sept line:', line[:500])
        break
